import{_ as e,o as r,c as a,a3 as i}from"./chunks/framework.fntC-tS-.js";const p=JSON.parse('{"title":"SGC Seminar Series 2024","description":"","frontmatter":{"title":"SGC Seminar Series 2024","date":"2024-01-09T00:00:00.000Z","author":"Ludovic Räss, Marj Tonini","tags":["Seminar-series","Event"]},"headers":[],"relativePath":"events/seminar-serie-2024-1.md","filePath":"events/seminar-serie-2024-1.md","lastUpdated":1794345340000}'),d={name:"events/seminar-serie-2024-1.md"};function n(o,t,s,l,c,m){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="sgc-seminar-series-2024" tabindex="-1">SGC Seminar Series 2024 <a class="header-anchor" href="#sgc-seminar-series-2024" aria-label="Permalink to &quot;SGC Seminar Series 2024&quot;">​</a></h1><p>The <strong>First SGC Seminar Series</strong> presents leading-edge research carried out by the members of the SGC Scientific Committee.</p><blockquote><p>The Swiss Geocomputing Centre (SGC) federates interdisciplinary research across geosciences. With a clear meaning of GeoComputing as emerging discipline at the intersection between geosciences and computation, our main purpose is to bring together researchers dealing with computational and modelling approaches and to promote related activities.</p></blockquote><p>It will be held from 15:30 to 16:30 at Geopolis and followed by an informal apero 🎉 !</p><table tabindex="0"><thead><tr><th>Date</th><th>Speaker</th><th>room</th><th>Title</th></tr></thead><tbody><tr><td><strong>18 Jan</strong></td><td>Marj Tonini</td><td>GEO 2113</td><td>Towards Geo-Data Science: practical concepts and environmental applications</td></tr><tr><td></td><td>Christian Kaiser</td><td></td><td>Analysis of mobility potential and behavior: a computational geography approach</td></tr><tr><td><strong>8 Feb</strong></td><td>Daniela Domeisen</td><td>GEO 2113</td><td>Modelling and predicting extreme weather events</td></tr><tr><td></td><td>Guillaume Jouvet</td><td></td><td>Glacier ice flow modelling based on Physics-informed deep learning</td></tr><tr><td><strong>22 Feb</strong></td><td>Tom Beucler</td><td>GEO 2235</td><td>Adding and calibrating uncertainty in neural networks for climate applications</td></tr><tr><td></td><td>Flavio Calvo &amp; Margot Sirdey</td><td></td><td>HPC success stories</td></tr><tr><td><strong>29 Feb</strong></td><td>Céline Rozenblat</td><td>GEO 2235</td><td>What could be the interest of the involvement of the Swiss Geocomputing Centre in the UN-GGIM: United Nations - Global Geospatial Information management ?</td></tr><tr><td>(TBC)</td><td>György Hetényi &amp; Ariane Maharaj</td><td>GEO 2235</td><td>Solid Earth geophysics: classical imaging and inversion for 3D structures</td></tr><tr><td><strong>14 Mar</strong></td><td>Gregoire Mariethoz</td><td>GEO 2235</td><td>Generating synthetic satellite observations</td></tr><tr><td></td><td>Stefan Schmalholz</td><td></td><td>Deterministic modeling in geodynamics: Towards 3D thermo-hydro-mechanical-chemical simulations</td></tr><tr><td></td><td>Ludovic Räss</td><td></td><td>Combining geo-HPC and tooling towards reproducible research</td></tr></tbody></table><p>Looking forward to seeing you there!</p>',6)])])}const g=e(d,[["render",n]]);export{p as __pageData,g as default};
